import unittest
from candidate import longest


class TestLongest(unittest.TestCase):
    def test_empty_list_returns_none(self):
        self.assertIsNone(longest([]))

    def test_single_element_returns_that_element(self):
        self.assertEqual(longest(['hello']), 'hello')

    def test_single_empty_string(self):
        self.assertEqual(longest(['']), '')

    def test_multiple_elements_returns_longest(self):
        self.assertEqual(longest(['a', 'bb', 'ccc']), 'ccc')

    def test_tie_returns_first_occurrence(self):
        self.assertEqual(longest(['a', 'b', 'c']), 'a')

    def test_tie_with_different_positions(self):
        self.assertEqual(longest(['ab', 'cd', 'ef']), 'ab')

    def test_tie_returns_first_not_last(self):
        self.assertEqual(longest(['zz', 'aa', 'bb']), 'zz')

    def test_empty_strings_all(self):
        self.assertEqual(longest(['', '', '']), '')

    def test_mixed_empty_and_non_empty(self):
        self.assertEqual(longest(['', 'ab', '']), 'ab')

    def test_longest_at_beginning(self):
        self.assertEqual(longest(['abcdef', 'abc', 'ab']), 'abcdef')

    def test_longest_at_end(self):
        self.assertEqual(longest(['ab', 'abc', 'abcdef']), 'abcdef')

    def test_longest_in_middle(self):
        self.assertEqual(longest(['ab', 'abcdef', 'abc']), 'abcdef')

    def test_two_elements_different_lengths(self):
        self.assertEqual(longest(['hi', 'hello']), 'hello')

    def test_two_elements_same_length(self):
        self.assertEqual(longest(['hi', 'hey']), 'hi')

    def test_unicode_strings(self):
        self.assertEqual(longest(['a', 'éé', 'üüü']), 'üüü')

    def test_strings_with_spaces(self):
        self.assertEqual(longest(['a', 'b c', 'd e f']), 'd e f')

    def test_strings_with_newlines(self):
        self.assertEqual(longest(['a', 'b\nc', 'd\ne\nf']), 'd\ne\nf')

    def test_large_list(self):
        strings = [chr(97 + i) * (i + 1) for i in range(26)]
        self.assertEqual(longest(strings), 'z'*26)

    def test_large_list_tie(self):
        strings = ['a' * 5, 'b' * 5, 'c' * 5]
        self.assertEqual(longest(strings), 'a' * 5)

    def test_none_input(self):
        with self.assertRaises((TypeError, AttributeError)):
            longest(None)

    def test_non_list_input_string(self):
        with self.assertRaises(TypeError):
            longest('hello')

    def test_non_list_input_int(self):
        with self.assertRaises(TypeError):
            longest(123)

    def test_non_string_elements_int(self):
        with self.assertRaises(TypeError):
            longest([1, 2, 3])

    def test_non_string_elements_none_in_list(self):
        with self.assertRaises(TypeError):
            longest([None, 'a', 'b'])

    def test_returns_string_type(self):
        result = longest(['a', 'bb'])
        self.assertIsInstance(result, str)

    def test_returns_none_type_for_empty(self):
        result = longest([])
        self.assertIsNone(result)

    def test_very_long_string(self):
        long_str = 'a' * 100000
        self.assertEqual(longest(['b', long_str, 'c']), long_str)

    def test_single_character_strings(self):
        self.assertEqual(longest(['x', 'y', 'z']), 'x')

    def test_mixed_lengths_various(self):
        self.assertEqual(longest(['abc', 'de', 'fghij', 'klmno']), 'fghij')

    def test_all_same_length_different_content(self):
        self.assertEqual(longest(['cat', 'dog', 'bird']), 'cat')

    def test_numeric_strings(self):
        self.assertEqual(longest(['1', '12', '123']), '123')

    def test_special_characters(self):
        self.assertEqual(longest(['!@#', '$%^&*()']), '$%^&*()')

    def test_tab_characters(self):
        self.assertEqual(longest(['a', 'b\tc', 'd']), 'b\tc')


if __name__ == '__main__':
    unittest.main()
